import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, positionLocal, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const pick = (role) => items.filter((i) => i.role === role);
  const kickerItem = pick('kicker')[0];
  const heroItems = pick('hero');
  const bodyItem = pick('body')[0];
  const captionItem = pick('caption')[0];

  const group = new Group();
  const disposables = [];
  const timelines = [];

  // ---- Backdrop editorial plate with vertical engineered gradient + grain ----
  const plateGeo = new PlaneGeometry(7, 5.5, 1, 1);
  const plateMat = new MeshBasicNodeMaterial();
  const topCol = vec3(...new Color(colors.gradientStops?.[0]?.hex ?? colors.background).toArray());
  const botCol = vec3(...new Color(colors.gradientStops?.[1]?.hex ?? colors.surface).toArray());
  const grainU = uniform(0.015);
  const vy = uv().y;
  const base = mix(botCol, topCol, vy);
  // cheap deterministic grain from uv
  const grain = uv().x.mul(uv().y).mul(97.0).fract().sub(0.5).mul(grainU);
  const platedColor = base.add(grain);
  plateMat.colorNode = vec4(platedColor, float(1.0));
  const plate = new Mesh(plateGeo, plateMat);
  plate.position.set(0, 0, -0.1);
  group.add(plate);
  disposables.push(plateGeo, plateMat);

  // ---- Text blocks ----
  const X = -3.1;
  const blocks = [];

  if (kickerItem) {
    const t = ctx.fontAtlas.createText(kickerItem.text, {
      fontSize: kickerItem.typography?.fontSize ?? 18,
      color: colors.paper,
      align: 'left',
      letterSpacingPx: 3,
    });
    t.position.set(X, 1.7, 0.02);
    t.scale.setScalar(0.9);
    group.add(t);
    blocks.push(t);
  }

  // Hero lines with letterpress shadow duplicate
  const heroYs = [0.9, 0.25];
  heroItems.forEach((h, idx) => {
    const y = heroYs[idx] ?? (0.9 - idx * 0.65);

    // letterpress shadow layer (behind)
    const shadow = ctx.fontAtlas.createText(h.text, {
      fontSize: h.typography?.fontSize ?? 124,
      color: colors.ink,
      align: 'left',
    });
    shadow.position.set(X + 0.015, y - 0.015, -0.02);
    group.add(shadow);
    blocks.push(shadow);

    const t = ctx.fontAtlas.createText(h.text, {
      fontSize: h.typography?.fontSize ?? 124,
      color: colors.paper,
      align: 'left',
    });
    t.position.set(X, y, 0.03);
    group.add(t);
    blocks.push(t);
  });

  // ---- Accent underline rule (brightest element / signal red emissive) ----
  const ruleGeo = new PlaneGeometry(2.2, 0.05, 1, 1);
  const ruleMat = new MeshStandardNodeMaterial();
  const accentCol = new Color(colors.accent);
  ruleMat.colorNode = vec3(...accentCol.toArray());
  ruleMat.emissiveNode = vec3(...accentCol.toArray()).mul(1.2);
  ruleMat.roughness = 0.6;
  ruleMat.metalness = 0.0;
  const rule = new Mesh(ruleGeo, ruleMat);
  // anchor left edge at X: plane centered, so offset by half width
  rule.position.set(X + 1.1, -0.15, 0.02);
  rule.scale.x = 0.0001;
  group.add(rule);
  disposables.push(ruleGeo, ruleMat);

  if (bodyItem) {
    const t = ctx.fontAtlas.createText(bodyItem.text, {
      fontSize: bodyItem.typography?.fontSize ?? 26,
      color: colors.paper,
      align: 'left',
      maxWidthPx: 620,
    });
    t.position.set(X, -0.8, 0.02);
    group.add(t);
    blocks.push(t);
  }

  if (captionItem) {
    const t = ctx.fontAtlas.createText(captionItem.text, {
      fontSize: captionItem.typography?.fontSize ?? 18,
      color: colors.paper,
      align: 'left',
      letterSpacingPx: 2,
    });
    t.position.set(X, -1.9, 0.02);
    t.scale.setScalar(0.9);
    group.add(t);
    blocks.push(t);
  }

  // ---- Entrance: rise-in top-to-bottom stagger ----
  const tl = gsap.timeline();
  timelines.push(tl);

  // sort blocks by descending y for top-to-bottom order
  const ordered = blocks
    .map((b) => ({ obj: b, y: b.position.y }))
    .sort((a, b) => b.y - a.y);

  ordered.forEach((entry, i) => {
    const obj = entry.obj;
    const finalY = obj.position.y;
    obj.position.y = finalY + 0.4;
    tl.fromTo(
      obj.position,
      { y: finalY + 0.4 },
      { y: finalY, duration: 0.7, ease: 'power3.out' },
      i * 0.08
    );
    if (obj.material) {
      obj.material.transparent = true;
      obj.material.opacity = 0;
      tl.to(obj.material, { opacity: 1, duration: 0.5, ease: 'power2.out' }, i * 0.08);
    } else if (obj.traverse) {
      obj.traverse((c) => {
        if (c.material) {
          c.material.transparent = true;
          c.material.opacity = 0;
        }
      });
      const targets = [];
      obj.traverse((c) => { if (c.material) targets.push(c.material); });
      tl.to(targets, { opacity: 1, duration: 0.5, ease: 'power2.out' }, i * 0.08);
    }
  });

  // rule draws after hero lands
  tl.to(rule.scale, { x: 1, duration: 0.5, ease: 'power2.out' }, 0.55);

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    disposables.forEach((d) => d.dispose && d.dispose());
    group.traverse((c) => {
      if (c.geometry && c.geometry.dispose) c.geometry.dispose();
      if (c.material && c.material.dispose) c.material.dispose();
    });
  };

  return group;
}
